class Solution {
public:
    vector<int> flips;
    int pos;
    bool impossible;

    void dfs(TreeNode* node, vector<int>& voyage) {
        if (!node || impossible) return;
        if (pos >= (int)voyage.size() || node->val != voyage[pos]) {
            impossible = true;
            return;
        }
        pos++;
        if (node->left) {
            if (pos < (int)voyage.size() && node->left->val == voyage[pos]) {
                dfs(node->left, voyage);
                dfs(node->right, voyage);
            } else if (node->right && pos < (int)voyage.size() && node->right->val == voyage[pos]) {
                flips.push_back(node->val);
                dfs(node->right, voyage);
                dfs(node->left, voyage);
            } else {
                impossible = true;
            }
        } else {
            dfs(node->right, voyage);
        }
    }

    vector<int> flipMatchVoyage(TreeNode* root, vector<int>& voyage) {
        flips.clear();
        pos = 0;
        impossible = false;
        dfs(root, voyage);
        if (impossible) return {-1};
        return flips;
    }
};
